def two_sum_sorted(values, target):
    left = 0
    right = len(values) - 1
    while left < right:
        total = values[left] + values[right]
        if total == target:
            return left, right
        if total < target:
            left = left + 1
        else:
            right = right - 1
    return None

print(two_sum_sorted([1, 2, 4, 7], 6))
print(two_sum_sorted([2, 2], 4))
print(two_sum_sorted([2], 4))

def find_sorted_pair(values, target):
    left = 0
    right = len(values) - 1
    while left < right:
        total = values[left] + values[right]
        if total == target:
            return left, right
        if total < target:
            left += 1
        else:
            right -= 1
    return None

print(find_sorted_pair([-3, 1, 2, 5], 3))
print(find_sorted_pair([2, 2], 4))
print(find_sorted_pair([2], 4))
print(find_sorted_pair([], 0))

def find_fixed_window(values, width, target):
    if width <= 0:
        raise ValueError('width must be positive')
    if width > len(values):
        return None
    total = 0
    for right, value in enumerate(values):
        total += value
        if right >= width:
            total -= values[right - width]
        if right >= width - 1 and total == target:
            return right - width + 1, right + 1
    return None

print(find_fixed_window([4, -1, 2], 2, 3))
print(find_fixed_window([1, 2, 3], 2, 5))
print(find_fixed_window([], 1, 0))
try:
    print(find_fixed_window([0], 0, 0))
except ValueError:
    print('ValueError')
